/// A character's Unicode General_Category.
#[expect(clippy::exhaustive_enums, reason = "Unicode's stability policy fixes the set")]
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
#[repr(u8)]
pub enum GeneralCategory {
    /// `Cn`: no character assigned.
    Unassigned = 0,
    /// `Cc`: a C0 or C1 control code.
    Control = 1,
    /// `Cf`: a format control, which draws nothing.
    Format = 2,
    /// `Co`: a private use character.
    PrivateUse = 3,
    /// `Cs`: a surrogate code point.
    Surrogate = 4,
    /// `Ll`: a lowercase letter.
    LowercaseLetter = 5,
    /// `Lm`: a modifier letter.
    ModifierLetter = 6,
    /// `Lo`: another letter, such as one of a script without case.
    OtherLetter = 7,
    /// `Lt`: a titlecase digraph.
    TitlecaseLetter = 8,
    /// `Lu`: an uppercase letter.
    UppercaseLetter = 9,
    /// `Mc`: a spacing mark, which takes room of its own.
    SpacingMark = 10,
    /// `Me`: an enclosing mark.
    EnclosingMark = 11,
    /// `Mn`: a nonspacing mark.
    NonspacingMark = 12,
    /// `Nd`: a decimal digit.
    DecimalNumber = 13,
    /// `Nl`: a letterlike number, such as a Roman numeral.
    LetterNumber = 14,
    /// `No`: another number, such as a fraction or a superscript digit.
    OtherNumber = 15,
    /// `Pc`: a connector, such as the underscore.
    ConnectPunctuation = 16,
    /// `Pd`: a dash or hyphen.
    DashPunctuation = 17,
    /// `Pe`: a closing bracket.
    ClosePunctuation = 18,
    /// `Pf`: a closing quotation mark.
    FinalPunctuation = 19,
    /// `Pi`: an opening quotation mark.
    InitialPunctuation = 20,
    /// `Po`: other punctuation.
    OtherPunctuation = 21,
    /// `Ps`: an opening bracket.
    OpenPunctuation = 22,
    /// `Sc`: a currency symbol.
    CurrencySymbol = 23,
    /// `Sk`: a modifier symbol, such as a spacing accent.
    ModifierSymbol = 24,
    /// `Sm`: a math symbol.
    MathSymbol = 25,
    /// `So`: another symbol.
    OtherSymbol = 26,
    /// `Zl`: the line separator.
    LineSeparator = 27,
    /// `Zp`: the paragraph separator.
    ParagraphSeparator = 28,
    /// `Zs`: a space.
    SpaceSeparator = 29,
}

