/// How a character sets in vertical text, its Unicode Vertical_Orientation (UAX #50).
#[non_exhaustive]
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
#[repr(u8)]
pub enum VerticalOrientation {
    /// `R`: sideways, turned a quarter clockwise, as Latin letters set.
    Rotated = 0,
    /// `Tr`: upright in a vertical form where one is drawn, else sideways.
    TransformedRotated = 1,
    /// `Tu`: upright, in a vertical form where one is drawn.
    TransformedUpright = 2,
    /// `U`: upright, as CJK ideographs set.
    Upright = 3,
}

